create table if not exists public.founder_chat_messages (id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,role text not null check(role in ('user','assistant')),content text not null check(char_length(content) between 1 and 12000),created_at timestamptz not null default now());create index if not exists founder_chat_owner_created_idx on public.founder_chat_messages(owner_id,created_at desc);alter table public.founder_chat_messages enable row level security;create policy "Approved founders read own chat" on public.founder_chat_messages for select to authenticated using(owner_id=(select auth.uid()) and (select public.is_approved_founder()));create policy "Approved founders insert own chat" on public.founder_chat_messages for insert to authenticated with check(owner_id=(select auth.uid()) and (select public.is_approved_founder()));